enum class EarthNaturalLandClass : std::uint8_t {
    Unknown=0, Land=1, Ocean=2
};
inline EarthNaturalLandClass earthNaturalLandClassAt(EarthGeoPoint p)
{
    if(!earthValidGeo(p)) return EarthNaturalLandClass::Unknown;
    const int y=std::min(179,static_cast<int>(std::floor(p.latitudeDeg+90.0)));
    const int x=std::min(359,static_cast<int>(
        std::floor(earthWrapLongitude(p.longitudeDeg)+180.0)));
    const std::size_t index=static_cast<std::size_t>(y)*360
        +static_cast<std::size_t>(x);
    const std::size_t hexIndex=(index>>3)*2;
    const auto nibble=[](char c)->unsigned int {
        return c>='0'&&c<='9' ? static_cast<unsigned int>(c-'0')
            : static_cast<unsigned int>(c-'a'+10);
    };
    const unsigned int value=nibble(EarthLandMaskHex[hexIndex])*16U
        +nibble(EarthLandMaskHex[hexIndex+1]);
    return value&(1U<<(index&7))
        ? EarthNaturalLandClass::Land
        : EarthNaturalLandClass::Ocean;
}
